exec(source)
OUT=ROOT/'output/documents/NutriCare_Investigacion_Web_Fatima_Oviedo.docx'
d.core_properties.title='Integración de Firebase en NutriCare web'
p('UNIVERSIDAD DON BOSCO').alignment=WD_ALIGN_PARAGRAPH.CENTER
p('Computación').alignment=WD_ALIGN_PARAGRAPH.CENTER
p('')
p('Integración de Firebase en NutriCare web','Title').alignment=WD_ALIGN_PARAGRAPH.CENTER
p('Arquitectura, autenticación y persistencia con Next.js','Subtitle').alignment=WD_ALIGN_PARAGRAPH.CENTER
p('Fátima Yesenia Oviedo').alignment=WD_ALIGN_PARAGRAPH.CENTER
p('8 de noviembre de 2026').alignment=WD_ALIGN_PARAGRAPH.CENTER
h('Resumen')
p('En este documento explico la integración de Firebase Authentication y Cloud Firestore en la versión web de NutriCare. Describo la arquitectura del proyecto, el acceso por correo y Google, la organización de los datos, las reglas y los módulos de seguimiento. También analizo las evidencias disponibles y las limitaciones observadas en la revisión del código. La aplicación web se ejecuta en la raíz del repositorio y utiliza Next.js; se documenta aquí de manera independiente de la aplicación móvil desarrollada con Expo.')
p('Palabras clave: aplicación web, Next.js, Firebase Authentication, Cloud Firestore, seguridad, nutrición.')
page('1 Introducción y objetivos')
paras('NutriCare busca facilitar el seguimiento entre nutricionista y paciente mediante expedientes, mediciones, consultas, planes, hábitos y fotografías. La versión web ofrece espacios diferenciados y usa Firebase para identificar al usuario y consultar los documentos que le corresponden.', 'Mi objetivo es explicar cómo se relacionan la interfaz, los servicios y las reglas de seguridad, así como presentar criterios verificables para evaluar el avance. Una función existente en el código, una captura y una prueba de integración aportan evidencias diferentes y deben interpretarse por separado.')
h('Objetivos específicos')
for t in ['Describir la estructura y las tecnologías de la versión web.','Explicar el flujo de autenticación y la relación entre cuentas y expedientes.','Documentar el modelo de Firestore, las consultas y las reglas de acceso.','Analizar los módulos, las evidencias, las pruebas y las mejoras pendientes.']:p(t,'List Bullet')
h('Alcance')
p('El análisis corresponde al repositorio revisado el 8 de noviembre de 2026. La interfaz web se ejecuta normalmente en localhost:3000; mobile contiene otro proyecto. Mostrar la web en un navegador estrecho no equivale a ejecutar la aplicación React Native en un teléfono.')
page('2 Fundamento tecnológico')
paras('Next.js organiza páginas y layouts en src/app mediante App Router. La documentación oficial describe la función de carpetas y archivos para estructurar rutas (Vercel, s. f.). React permite construir componentes y compartir el estado de autenticación. TypeScript aporta comprobación estática y Zod valida datos recibidos de formularios.', 'Firebase Authentication administra las identidades. Firestore organiza los datos en colecciones y documentos (Google, s. f.-b). El navegador utiliza el SDK de Firebase para solicitar datos con la identidad activa; las reglas evalúan cada solicitud. En package.json varias dependencias se declaran como latest, por lo que para conocer la versión realmente instalada se debe consultar el archivo de bloqueo.')
table(['Tecnología','Uso en NutriCare web'], [('Next.js y React','Rutas, componentes, formularios y navegación.'),('Firebase Authentication','Registro, acceso, Google, recuperación y sesión.'),('Cloud Firestore','Perfiles, expedientes y seguimiento.'),('React Hook Form y Zod','Captura y validación de información.'),('Playwright y emuladores','Pruebas automatizadas del navegador y las reglas.')],[2.0,4.6])
page('3 Arquitectura y carpetas')
p('La interfaz solicita operaciones a servicios. Cuando Firebase está configurado, apiClient deriva las operaciones clínicas a cloudRecords; este utiliza el SDK y la sesión de Firebase. Con la configuración remota activa, proxy responde 410 para las rutas API antiguas salvo status, evitando usarlas como fuente de datos clínicos.')
code('Pantallas y componentes en src/app y src/components\n    ↓\nContexto de acceso y servicios en src/context y src/services\n    ↓\nSDK de Firebase → Authentication y Firestore\n    ↓\nReglas de seguridad y documentos autorizados')
table(['Ubicación','Responsabilidad'], [('src/app/(auth)','Pantallas de acceso, registro y recuperación.'),('src/app/(dashboard)','Panel, pacientes, consultas, planes, mediciones, fotos e historial.'),('src/components','Formularios, navegación y componentes reutilizables.'),('src/context y src/hooks','Estado compartido y acceso a la sesión.'),('src/services','Operaciones de autenticación y registros.'),('src/schemas y src/types','Validaciones y tipos de datos.'),('src/lib/firebase','Inicialización de los servicios Firebase.'),('firestore.rules y tests','Reglas y pruebas de seguridad e integración.')],[2.6,4.0])
page('4 Autenticación y sesión')
paras('El formulario de registro recoge nombre, correo, contraseña y tipo de cuenta. authService usa createUserWithEmailAndPassword, actualiza el nombre y crea users/{uid}. El registro de Authentication y la escritura del perfil son operaciones separadas. Si no se confirma el perfil, la aplicación avisa que la cuenta pudo crearse y recomienda intentar iniciar sesión antes de repetir el registro.', 'El acceso por correo utiliza signInWithEmailAndPassword. El acceso con Google usa GoogleAuthProvider y signInWithPopup; cuando no existe un perfil, el código crea uno con rol paciente. La documentación de Firebase explica el método de ventana emergente para JavaScript (Google, s. f.-a). Su funcionamiento remoto depende también de la configuración del proveedor y los dominios autorizados.', 'AuthContext recibe los cambios mediante onAuthStateChanged, carga el perfil y comparte user y loading. ProtectedRoute espera mientras se comprueba la sesión y redirige al login si falta usuario. El cierre ejecuta signOut. Cambiar la contraseña de una cuenta de correo exige reautenticación; el perfil ofrece recuperación de acceso.')
h('Cuenta y expediente')
p('El expediente que crea la nutricionista en Pacientes es un documento de records, no una cuenta en Authentication. El paciente crea su propia cuenta con el mismo correo y debe verificarlo para leer los registros compartidos. La interfaz ofrece enviar la verificación y actualizar el estado del correo. La verificación comprueba el control del correo, no la formación profesional.')
page('5 Modelo de datos en Firestore')
p('El proyecto agrupa los registros de seguimiento en records/{id}. El campo kind identifica el módulo y payload guarda los datos específicos como JSON. Esta decisión permite una capa de persistencia compartida, aunque dificulta buscar directamente por campos internos.')
table(['Colección o campo','Función'], [('users/{uid}','Perfil con identificador, nombre, correo y rol.'),('settings/{uid}','Preferencias y notificaciones leídas.'),('records/{id}','Expedientes, mediciones, consultas, planes, fotos y hábitos.'),('ownerId y authorId','Identifican al propietario y al autor.'),('patientId y patientEmail','Relacionan el expediente y el correo del paciente.'),('createdAt, updatedAt y archived','Fechas y estado de archivo del registro.'),('payload, feedback y approved','Contenido del módulo y revisión de fotografías.')],[2.5,4.1])
p('Los planes usan un identificador derivado del propietario, paciente y mes; los hábitos usan usuario y fecha. La escritura utiliza una transacción para comprobar y guardar el documento. Las reglas y los servicios procuran mantener los campos de identidad sin cambios durante las ediciones.')
page('6 Consultas, historial y sincronización')
paras('listCloudRecords consulta por ownerId y, para un usuario con correo verificado, también por patientEmail. Puede añadir el filtro kind; combina resultados sin duplicados y aplica en el cliente parte del filtrado y ordenamiento. La aplicación consulta de nuevo al cargar o actualizar una pantalla. En el código revisado no se utiliza un listener onSnapshot para mantener estas listas actualizadas en tiempo real.', 'El historial muestra registros disponibles y archivados, con filtros y una acción Actualizar. Archivar conserva el documento y lo retira de las vistas activas; el historial muestra su estado y fechas, pero no constituye una bitácora inmutable de todas las versiones.', 'firestore.indexes.json excluye payload de indexación y no declara índices compuestos. Esto evita indexar el texto que no se consulta por campos internos, pero no acredita por sí solo una optimización completa. Al crecer el volumen propongo paginación, campos tipados para búsquedas y medición de rendimiento.')
page('7 Seguridad y protección de datos')
paras('Las reglas de la raíz verifican la identidad con request.auth y establecen acceso por propiedad o por correo del destinatario verificado. También validan campos, límites y relaciones con el expediente. La eliminación física de records está denegada y se usa el archivo lógico. Firebase documenta estas condiciones como parte de sus Security Rules (Google, s. f.-d).', 'El rol se selecciona al registrar la cuenta y organiza la interfaz, pero no acredita que una persona sea nutricionista. Por ello, ocultar botones no sustituye la autorización de Firestore. Las reglas limitan payload como cadena, pero no comprueban cada dato clínico dentro del JSON. Antes de un uso real se necesita una revisión de seguridad, validación de campos tipados y control de roles profesionales.', 'Existe una ruta local de demostración cuando Firebase no está configurado; almacena cuentas y contraseñas en localStorage. No es adecuada para datos reales y debe retirarse o protegerse antes de una publicación. La configuración NEXT_PUBLIC identifica el proyecto cliente; no reemplaza las reglas ni debe incluir credenciales privadas de servicio.')
page('8 Módulos y decisiones de implementación')
table(['Módulo','Funcionamiento observado'], [('Pacientes','La nutricionista crea el expediente con correo, nacimiento, estatura y objetivo.'),('Mediciones','Usa la estatura del expediente para calcular el IMC y guardar el control.'),('Consultas','Programa fecha, hora y modalidad, con notas y estado.'),('Planes','Organiza un plan mensual, comidas y recomendaciones.'),('Hábitos','Guarda comidas completadas y agua por usuario y fecha.'),('Fotografías','El paciente comparte una imagen y comentario; el propietario puede responder y aprobar.'),('Historial','Permite consultar registros y archivados según acceso.')],[1.5,5.1])
p('Las fotografías web se redimensionan en el navegador y se codifican como JPEG en el contenido del documento. Hay límites de tamaño para evitar documentos demasiado grandes. Esta solución facilita el prototipo, pero incrementar el número de imágenes puede elevar el tamaño y costo de las lecturas; un servicio de objetos con reglas propias sería una mejora para estudiar.')
page('9 Evidencia visual de la versión web')
x=p('Figura 1');x.runs[0].bold=True
x=p('Pantalla de acceso de NutriCare web');x.runs[0].italic=True
x=p();x.alignment=WD_ALIGN_PARAGRAPH.CENTER;x.add_run().add_picture(str(ROOT/'.local-tools/qa-login-web.png'),width=Inches(6.25))
note('Captura local de la interfaz web. El botón de Google es evidencia de la interfaz, no de un acceso remoto completado.')
paras('La pantalla presenta ingreso por correo, recuperación, creación de cuenta y el botón de Google. Esta captura permite evaluar la interfaz; para verificar el flujo se necesita iniciar sesión con una cuenta de prueba.', 'La carpeta .local-tools contiene además una captura del historial web a un ancho de 390 píxeles obtenida por la prueba de navegador. Esa captura corresponde a diseño adaptable de la web, no a una prueba nativa de React Native.')
page('10 Pruebas y resultados documentados')
p('El repositorio contiene tests/firestore-rules.test.mjs y tests/e2e/web.spec.ts. Las pruebas usan el proyecto local demo-nutricare, con emuladores de Authentication y Firestore. El recorrido automatizado crea cuentas de prueba, expediente, medición, consulta, plan, hábitos, fotografía y retroalimentación; también revisa perfil y cierre de sesión.')
p('El archivo docs/WEB-FIREBASE.md registra una ejecución del 6 de noviembre de 2026 con 15 pruebas de reglas y dos pruebas de navegador aprobadas, además de compilación y TypeScript. Estos son resultados históricos documentados en el repositorio; no se presentan como una nueva ejecución completa en esta revisión. El acceso con Google mediante una cuenta real quedó pendiente en ese registro.')
table(['Prueba','Qué se debe observar'], [('Acceso inválido','Mensaje de error y ausencia de acceso al panel.'),('Guardado','Expediente y medición en la interfaz y en records.'),('Paciente verificado','Lectura solo de los registros asociados a su correo.'),('Acceso ajeno','Solicitud de lectura rechazada por las reglas.'),('Historial','Datos disponibles y archivados, con sus fechas.'),('Fotografía','Imagen y respuesta visibles después de recargar.')],[2.2,4.4])
page('11 Ejecución y validación práctica')
p('Desde una terminal PowerShell abierta en la carpeta raíz nutricare:')
code('pnpm install --frozen-lockfile\npnpm dev')
p('Se abre http://localhost:3000/login y se mantiene la terminal activa. Las variables NEXT_PUBLIC_FIREBASE_* deben estar configuradas en .env.local con el proyecto correspondiente. Si cambia la configuración, reinicia el servidor. No se deben incluir claves privadas de cuentas de servicio en el cliente.')
h('Pruebas reproducibles')
code('pnpm typecheck\npnpm exec eslint src tests playwright.config.ts\npnpm build\npowershell -NoProfile -ExecutionPolicy Bypass -File scripts/test-web.ps1')
p('El script de integración requiere Firebase CLI, Java 21 y Chrome; utiliza emuladores para evitar crear datos en el proyecto remoto. Los resultados deben registrarse en el momento de la ejecución. Para comprobar Google también se requiere una cuenta real de prueba y la configuración correcta del proyecto.')
h('Prueba manual de la base remota')
p('Crear un expediente ficticio, buscarlo en Firestore → records por kind y patientEmail, recargar la aplicación y comprobar que permanece. Después simular o intentar una lectura con otra cuenta. Una captura de la consola de administración por sí sola no demuestra que un cliente no autorizado sea rechazado.')
page('12 Reflexión y conclusiones')
paras('Como estudiante de Computación, comprendí que la integración no consiste solamente en mostrar un formulario. Cada dato necesita una relación clara con su propietario y con el paciente que tiene permiso para consultarlo. Separar Authentication de los expedientes me ayudó a explicar por qué una persona puede aparecer en Pacientes sin tener todavía una cuenta de acceso.', 'Firebase facilita los servicios de identidad y almacenamiento, pero también exige decidir las reglas, validar los datos y probar los límites. La navegación por roles mejora la experiencia, mientras que la autorización debe comprobarse en la base de datos. También observé que un historial de registros no es automáticamente una auditoría completa.', 'Considero prioritario eliminar el modo local con contraseñas para un uso real, verificar la acreditación profesional, unificar los contratos de datos de web y móvil y mejorar el tratamiento de imágenes. Para sincronización continua se pueden evaluar listeners, con manejo de errores y cancelación de suscripciones (Google, s. f.-c).', 'Concluyo que NutriCare web dispone de una arquitectura que integra identidad, persistencia y seguimiento. Sus pruebas y capturas ayudan a explicar el avance, mientras que la validación remota, la privacidad y el comportamiento entre plataformas deben seguir comprobándose antes de utilizar datos clínicos reales.')
page('13 Referencias')
refs=[('Google. (s. f.-a).','Authenticate using Google with JavaScript.','Firebase.','https://firebase.google.com/docs/auth/web/google-signin'),('Google. (s. f.-b).','Cloud Firestore data model.','Firebase.','https://firebase.google.com/docs/firestore/data-model'),('Google. (s. f.-c).','Get realtime updates with Cloud Firestore.','Firebase.','https://firebase.google.com/docs/firestore/query-data/listen'),('Google. (s. f.-d).','Writing conditions for Cloud Firestore Security Rules.','Firebase.','https://firebase.google.com/docs/firestore/security/rules-conditions'),('Google. (s. f.-e).','Test your Cloud Firestore Security Rules.','Firebase.','https://firebase.google.com/docs/firestore/security/test-rules-emulator'),('Vercel. (s. f.).','Project structure and organization.','Next.js.','https://nextjs.org/docs/app/getting-started/project-structure')]
for author,title,site,url in refs:
 x=p();x.add_run(author+' ');x.add_run(title).italic=True;x.add_run(' '+site+' '+url);x.paragraph_format.left_indent=Inches(.3);x.paragraph_format.first_line_indent=Inches(-.3);x.paragraph_format.space_after=Pt(14)
